import {
  DefinitionsLimitBanner,
  isDefinitionsLimitReached,
} from '@github-ui/custom-properties-core/components/DefinitionsLimitBanner'
import {PropertyPageHeader} from '@github-ui/custom-properties-core/components/PropertyPageHeader'
import {Link} from '@github-ui/react-core/link'
import {Button} from '@primer/react'
import {getPropertyDetailsPath} from '../paths'
import {useBusinessSlug} from '../hooks/use-business-slug'

interface Props {
  ownDefinitionsCount: number
}

export function BusinessSettingsHeader({ownDefinitionsCount}: Props) {
  const businessSlug = useBusinessSlug()
  const newPropertyPath = getPropertyDetailsPath({business: businessSlug})
  const definitionLimitReached = isDefinitionsLimitReached(ownDefinitionsCount)

  return (
    <>
      <PropertyPageHeader
        title="Custom properties"
        subtitle="Custom properties allow you to decorate your organizations with information such as compliance frameworks, data
    sensitivity, or project details."
        actions={
          !definitionLimitReached && (
            <Button as={Link} to={newPropertyPath} variant="primary" data-testid="add-definition-button">
              New property
            </Button>
          )
        }
      />
      {definitionLimitReached && (
        <div className="mb-2">
          <DefinitionsLimitBanner />
        </div>
      )}
    </>
  )
}

try{ BusinessSettingsHeader.displayName ||= 'BusinessSettingsHeader' } catch {}