export function getPropertyDetailsPath({business, propertyName}: {business: string; propertyName?: string}) {
  const base = `/enterprises/${encodeURIComponent(business)}/settings/org-custom-property`

  if (propertyName) {
    return `${base}/${encodeURIComponent(propertyName)}`
  }

  return base
}

export function getPropertiesListPath({business}: {business: string}) {
  return `/enterprises/${encodeURIComponent(business)}/settings/org-custom-properties`
}

export function getPropertiesUsagePath({business, propertyName}: {business: string; propertyName: string}) {
  return `/enterprises/${encodeURIComponent(business)}/settings/org-custom-properties-usage/${encodeURIComponent(
    propertyName,
  )}`
}

export function updatePropertyValuesFromBizPath({business}: {business: string}) {
  return `/enterprises/${encodeURIComponent(business)}/settings/org-custom-properties/values`
}

export function getOrgSettingsUpdatePropertiesPath({org}: {org: string}) {
  return `/organizations/${encodeURIComponent(org)}/settings/org-custom-properties/values`
}
