import {PropertiesBreadcrumbsPageHeader} from '@github-ui/custom-properties-core/components/PropertiesBreadcrumbsPageHeader'
import {PropertiesEditingPage} from '@github-ui/custom-properties-core/components/PropertiesEditingPage'
import {PropertiesPageTabs} from '@github-ui/custom-properties-core/components/PropertiesPageTabs'
import {TargetsList} from '@github-ui/custom-properties-core/components/TargetsList'
import {useBannerContext} from '@github-ui/custom-properties-core/context/BannerContext'
import type {OrganizationTarget} from '@github-ui/custom-properties-types/org-properties'
import {Filter} from '@github-ui/filter'
import {ownerPath} from '@github-ui/paths'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useSearchParams} from '@github-ui/react-router'
import {Pagination} from '@primer/react'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import {BusinessSettingsHeader} from '../components/BusinessSettingsHeader'
import {useBusinessSlug} from '../hooks/use-business-slug'
import {updatePropertyValuesFromBizPath} from '../paths'
import {
  businessCustomPropertiesSettingsRoute,
  type BusinessSetValuesRouteResponse,
} from './business-custom-properties-settings-route'
import {useQueryClient} from '@github-ui/react-query'
import {OrganizationIcon} from '@primer/octicons-react'

export function BusinessSetValuesRoute() {
  const queryClient = useQueryClient()
  const {data, queryKey, setFilterValue, setCurrentPage, initialFilterValue, currentPage} = useOrgsListQuery()

  const {definitions, orgs, pageCount, totalCount} = data
  const business = useBusinessSlug()

  const [editingOrgs, setEditingOrgs] = useState<OrganizationTarget[]>([])
  const editableProperties = useMemo(() => definitions.map(d => d.propertyName), [definitions])

  const [selectedOrgIds, setSelectedOrgIds] = useState<Set<number>>(() => new Set())

  const {setBanner} = useBannerContext()

  const selectOrgs = useCallback(
    (orgSelections: OrganizationTarget[], buttonId: string) => {
      setBanner(null)
      setEditingOrgs(orgSelections)
      clickedEditButtonRef.current = {buttonId, offset: window.scrollY}
    },
    [setEditingOrgs, setBanner],
  )

  const clickedEditButtonRef = useRef<null | {buttonId: string; offset: number}>(null)

  const isEditing = !!editingOrgs.length
  useEffect(() => {
    const {buttonId, offset} = clickedEditButtonRef.current || {}
    if (!isEditing && buttonId) {
      const button = document.getElementById(buttonId)
      button?.focus()
      window.scrollTo({top: offset})
    }
  }, [isEditing])

  if (isEditing) {
    const closePage = () => setEditingOrgs([])

    const pageTitle =
      editingOrgs.length === 1
        ? `Set properties on ${editingOrgs[0]?.login}`
        : `Set properties on ${editingOrgs.length} selected organizations`

    return (
      <PropertiesEditingPage
        definitions={definitions}
        editableProperties={editableProperties}
        onClose={closePage}
        onSuccess={() => {
          setBanner('values.updated.success')
          queryClient.invalidateQueries({queryKey})
          closePage()
        }}
        editingTargets={editingOrgs}
        renderPageHeader={({canClose}) => (
          <PropertiesBreadcrumbsPageHeader
            className="mb-3"
            pageTitle={pageTitle}
            breadcrumbLinkProps={{
              to: '#',
              onClick: async e => {
                e.preventDefault()
                if (await canClose()) closePage()
              },
            }}
          />
        )}
        setValuesPath={updatePropertyValuesFromBizPath({business})}
      />
    )
  }

  return (
    <>
      <BusinessSettingsHeader ownDefinitionsCount={definitions.length} />
      <PropertiesPageTabs definitionsCount={definitions.length} initialActiveTab="set-values" className="mb-3" />

      <Filter
        id="organizations-filter"
        label="Filter organizations"
        initialFilterValue={initialFilterValue}
        className="mb-3"
        providers={[]}
        onSubmit={({raw}) => setFilterValue(raw)}
        variant="input"
      />

      <TargetsList
        title="Organizations"
        targetLiterals={{
          single: 'organization',
          multiple: 'organizations',
        }}
        targets={orgs}
        totalCount={totalCount}
        onEditTargetPropertiesClick={selectOrgs}
        onSelectionChange={setSelectedOrgIds}
        selectedTargetIds={selectedOrgIds}
        renderItem={(org, itemProps) => (
          <TargetsList.Item
            key={org.id}
            name={org.login}
            properties={org.properties}
            linkToTarget={ownerPath({owner: org.login})}
            leadingIcon={OrganizationIcon}
            {...itemProps}
          />
        )}
      />

      {pageCount > 1 && (
        <Pagination
          currentPage={currentPage}
          pageCount={pageCount}
          onPageChange={(e, page) => {
            e.preventDefault() // Prevent click event from navigating
            setCurrentPage(page)
          }}
        />
      )}
    </>
  )
}

function useOrgsListQuery() {
  const [searchParams, setSearchParams] = useSearchParams()
  const {data, queryKey} = useRouteQuery(businessCustomPropertiesSettingsRoute, 'mainQuery')

  return {
    data: data as BusinessSetValuesRouteResponse,
    queryKey,
    initialFilterValue: searchParams.get('q') || '',
    setFilterValue: (value: string) => {
      const params = new URLSearchParams(searchParams)
      params.set('page', '1')
      params.set('q', value)

      setSearchParams(params)
    },
    currentPage: Number(searchParams.get('page')) || 1,
    setCurrentPage: (page: number) => {
      const params = new URLSearchParams(searchParams)
      params.set('page', `${page}`)

      setSearchParams(params)
    },
  }
}

try{ BusinessSetValuesRoute.displayName ||= 'BusinessSetValuesRoute' } catch {}